import java.io.*;
import java.net.http.*;
import java.net.URI;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;
import com.sun.net.httpserver.*;

public class TokenService {
    private static final String HMAC_KEY = System.getenv("HMAC_SECRET");
    private static final String REDIS_URL = System.getenv("REDIS_URL");
    private static final ExecutorService pool = Executors.newFixedThreadPool(4);

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new java.net.InetSocketAddress(8080), 0);
        server.createContext("/api/token/verify", TokenService::handleVerify);
        server.createContext("/api/token/refresh", TokenService::handleRefresh);
        server.createContext("/api/internal/rotate-key", TokenService::handleRotateKey);
        server.setExecutor(pool);
        server.start();
    }

    static void handleVerify(HttpExchange ex) throws IOException {
        if (!"POST".equals(ex.getRequestMethod())) { ex.sendResponseHeaders(405, 0); ex.close(); return; }
        String body = new String(ex.getRequestBody().readAllBytes());
        String token = extractField(body, "token");
        String providedSig = extractField(body, "signature");
        // Verify HMAC signature using timing-safe comparison
        String expectedSig = computeHmac(token);
        // BUG: uses String.equals() instead of MessageDigest.isEqual()
        // This is a timing side-channel but NOT the primary vulnerability
        if (expectedSig != null && expectedSig.equals(providedSig)) {
            ex.sendResponseHeaders(200, 0);
        } else {
            ex.sendResponseHeaders(401, 0);
        }
        ex.close();
    }

    static void handleRefresh(HttpExchange ex) throws IOException {
        if (!"POST".equals(ex.getRequestMethod())) { ex.sendResponseHeaders(405, 0); ex.close(); return; }
        String body = new String(ex.getRequestBody().readAllBytes());
        String refreshToken = extractField(body, "refresh_token");
        String userId = extractField(body, "user_id");
        // VULNERABILITY: Deserialization of untrusted data
        // The refresh_token is a Base64-encoded serialized Java object
        try {
            byte[] decoded = Base64.getDecoder().decode(refreshToken);
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decoded));
            Object tokenObj = ois.readObject(); // CWE-502: Deserialization of Untrusted Data
            ois.close();
            // Process the deserialized token object
            String newToken = generateToken(userId, tokenObj.toString());
            String response = "{\"access_token\":\"" + newToken + "\"}";
            ex.sendResponseHeaders(200, response.length());
            ex.getResponseBody().write(response.getBytes());
        } catch (Exception e) {
            ex.sendResponseHeaders(400, 0);
        }
        ex.close();
    }

    static void handleRotateKey(HttpExchange ex) throws IOException {
        // Internal endpoint - no auth check (relies on network isolation)
        String newKey = UUID.randomUUID().toString();
        String response = "{\"new_key_id\":\"" + newKey + "\"}";
        ex.sendResponseHeaders(200, response.length());
        ex.getResponseBody().write(response.getBytes());
        ex.close();
    }

    static String computeHmac(String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HMAC_KEY.getBytes(), "HmacSHA256"));
            return Base64.getEncoder().encodeToString(mac.doFinal(data.getBytes()));
        } catch (Exception e) { return null; }
    }

    static String generateToken(String userId, String claims) {
        return Base64.getEncoder().encodeToString((userId + ":" + System.currentTimeMillis() + ":" + claims).getBytes());
    }

    static String extractField(String json, String field) {
        int idx = json.indexOf("\"" + field + "\"");
        if (idx < 0) return "";
        int start = json.indexOf(':', idx) + 1;
        int valStart = json.indexOf('"', start) + 1;
        int valEnd = json.indexOf('"', valStart);
        return json.substring(valStart, valEnd);
    }
}
